-- GAS-CP-R97-040 (v1.140.0) — Newsletter lists; website subscribers become contacts; origin / review mark on contacts
ALTER TABLE contacts ADD COLUMN origin VARCHAR(20) NULL;
ALTER TABLE contacts ADD COLUMN needs_review TINYINT NOT NULL DEFAULT 0;
ALTER TABLE nl_subs ADD COLUMN contact_id INT NULL;
ALTER TABLE nl_subs ADD COLUMN role VARCHAR(30) NULL;
CREATE TABLE IF NOT EXISTS nl_lists (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, descr VARCHAR(300) NULL, filter TEXT NULL, add_emails TEXT NULL, skip_emails TEXT NULL, created_by INT NULL, created_name VARCHAR(120) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
